import { createServer } from 'node:http'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { basename, join } from 'node:path'

const args = process.argv.slice(2)

async function readProfileManifest(path) {
  try {
    return JSON.parse(await readFile(path, 'utf8'))
  }
  catch (error) {
    if (error.code === 'ENOENT')
      return {}
    throw error
  }
}

async function installPlugins(commandArgs) {
  const profileIndex = commandArgs.indexOf('--profile')
  const addIndex = commandArgs.indexOf('add')
  const dshHome = process.env.DSH_HOME
  if (!dshHome || profileIndex < 0 || addIndex < 0 || !commandArgs[profileIndex + 1])
    throw new Error('invalid fixture plugin command')

  const profile = commandArgs[profileIndex + 1]
  const specs = commandArgs.slice(addIndex + 1)
  const profileDir = join(dshHome, 'profiles', profile)
  const profileManifestPath = join(profileDir, 'package.json')
  const profileManifest = await readProfileManifest(profileManifestPath)
  profileManifest.dependencies ??= {}
  profileManifest.dsh ??= {}
  profileManifest.dsh.profile ??= {}
  profileManifest.dsh.profile.bundles ??= []

  for (const spec of specs) {
    const packageName = basename(spec.replace(/^link:/, '').replaceAll('\\', '/'))
    if (!packageName)
      throw new Error(`invalid fixture plugin spec: ${spec}`)
    const packageDir = join(profileDir, 'node_modules', packageName)
    await mkdir(packageDir, { recursive: true })
    await writeFile(
      join(packageDir, 'package.json'),
      `${JSON.stringify({ name: packageName, version: '0.0.0-e2e' }, null, 2)}\n`,
    )
    profileManifest.dependencies[packageName] = spec
    if (!profileManifest.dsh.profile.bundles.includes(packageName))
      profileManifest.dsh.profile.bundles.push(packageName)
  }

  await mkdir(profileDir, { recursive: true })
  await writeFile(profileManifestPath, `${JSON.stringify(profileManifest, null, 2)}\n`)
  console.log(`installed ${specs.length} fixture plugins`)
}

if (args[0] === 'plugin') {
  await installPlugins(args)
  process.exit(0)
}

const portIndex = args.indexOf('--port')
const port = Number(args[portIndex + 1])
const token = 'E2E_ONE_SHOT_TOKEN'
const cookie = 'dsh-e2e=signed'

function authenticated(request) {
  return request.headers.cookie?.split(';').some(value => value.trim() === cookie) === true
}

const server = createServer((request, response) => {
  if (request.url === `/?token=${token}`) {
    console.log('E2E fixture auth exchange request')
    response.writeHead(303, {
      'cache-control': 'no-store',
      location: '/',
      'set-cookie': `${cookie}; Path=/; HttpOnly; SameSite=Strict`,
    })
    response.end()
    return
  }
  if (request.url === '/api/settings/describe' && request.method === 'POST') {
    const authorized = authenticated(request)
    console.log(`E2E fixture protected request authenticated=${authorized}`)
    response.writeHead(authorized ? 200 : 401, { 'content-type': 'application/json' })
    response.end(authorized ? '{}' : '{"error":"unauthorized"}')
    return
  }
  if (request.url === '/e2e-rendered' && request.method === 'POST') {
    if (!authenticated(request)) {
      response.writeHead(401)
      response.end()
      return
    }
    console.log('E2E fixture child script executed')
    response.writeHead(204)
    response.end()
    return
  }
  if (request.url === '/' && authenticated(request)) {
    console.log('E2E fixture authenticated root document')
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' })
    response.end('<!doctype html><main id="e2e-core-ready">Authenticated local core</main><script>fetch("/e2e-rendered",{method:"POST",credentials:"same-origin"})</script>')
    return
  }
  response.writeHead(401, { 'content-type': 'text/plain' })
  response.end('unauthorized')
})

server.listen(port, '127.0.0.1', () => {
  console.log(`dsh web: http://127.0.0.1:${port}/?token=${token}`)
})
